parts.quoted_text:
def reverse_string(s):
    result = ""
    for i in range(len(s) - 1, -1, -1):
        result += s[i]
    return result

print(reverse_string("hello"))

def deduplicate_list(lst):
    seen = []
    for item in lst:
        if item not in seen:
            seen.append(item)
    return seen

print(deduplicate_list([1, 2, 2, 3, 1, 4]))

def deduplicate_list(lst):
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

print(deduplicate_list([1, 2, 2, 3, 1, 4]))

